"status": "draft", "id": "1f8aa3dc-1fc4-5069-9ac3-31794639c96d"}, {"name": "孙儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：孙儒。", "biography": null, "status": "draft", "id": "4426793f-0bd8-5a79-919f-7e3a0ddae520"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "卢彦威", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：卢彦威。", "biography": null, "status": "draft", "id": "57740e74-d82d-506c-8996-dc6402924d88"}, {"name": "杨全玫", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：杨全玫。", "biography": null, "status": "draft", "id": "26ca8a59-b4cc-5d58-9386-1c99f62f3591"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "罗弘信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：罗弘信。", "biography": null, "status": "draft", "id": "da48e163-21a8-54a2-a3a0-cdef2344d96a"}, {"name": "胡真", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "朱温亲将，882年与谢瞳劝朱温归唐。", "biography": "朱温亲将，882年与谢瞳劝朱温归唐。", "status": "draft", "id": "091ba320-f158-5b07-9a25-feebc1f0e200"}, {"name": "葛从周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的葛从周，在此段中为降朱全忠者。", "biography": null, "status": "draft", "id": "26557449-8ad3-53a2-9cda-77849bf316c9"}, {"name": "李谠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李谠，在此段中为降朱全忠者。", "biography": null, "st