INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "张浚出师，昭宗安喜楼饯行", "start_year": 890, "end_year": 890, "time_original": "890年五月壬子", "dynasty": "唐", "description": "张浚率诸军及邠、宁、鄜、夏部众出京师，昭宗在安喜楼饯行。张浚私言先除外忧再除内患，杨复恭偷听得知。", "phases": [], "location_name": "京师、安喜楼", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0161dd19-bcd0-5563-a14c-522908fbd7bc"}, {"title": "张浚杨复恭长乐坂饯席交锋", "start_year": 890, "end_year": 890, "time_original": "890年五月壬子条；出师时", "dynasty": "唐", "description": "两军中尉在长乐坂饯张浚，杨复恭劝酒，张浚以醉辞；两人言语相讥，杨复恭更加忌恨张浚。", "phases": [], "location_name": "长乐坂", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "66c8af6d-ef5a-5eb4-bb96-92a29d62c121"}, {"title": "朝廷削夺李罕之官爵", "start_year": 890, "end_year": 890, "time_original": "890年五月癸丑", "dynasty": "唐", "description": "朝廷削夺李罕之官爵。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "c42eca1f-a2e0-571a-9780-8ee27b77dd09"}, {"title": "孙揆任昭义节度使兼招讨副使", "start_year": 890, "end_year": 890, "time_original": "890年六月", "dynasty": "唐", "description": "朝廷以孙揆为昭义节度使，充招讨副使。", "phases": [], "location_name": "昭义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3928cb5e-519f-51f1-bc7e-0e68e1703342"}, {"title": "李继昌援成都被王建击斩", "start_year": 890, "end_year": 890, "time_original": "890年六月丁巳至己未", "dynasty": "唐", "description": "茂州刺史李继昌率众救成都，王建在己未击败并斩杀李继昌。", "phases": [], "location_name": "成都方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e48c8d8c-97d8-55dd-bd26-26d1b61ed24d"}, {"title": "谢从本杀张承简举雅州降王建", "start_year": 890, "end_year": 890, "time_original": "890年六月辛酉", "dynasty": "唐", "description": "资简都制置应援使谢从本杀雅州刺史张承简，举城投降王建。", "phases": [], "location_name": "雅州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "918ae2a2-33c0-57a2-9867-8530eb13714d"}, {"title": "孙儒求好，朱全忠表请授淮南节度使", "start_year": 890, "end_year": 890, "time_original": "890年六月条；具体日未载", "dynasty": "唐", "description": "孙儒向朱全忠求好，朱全忠上表请其为淮南节度使。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "5e6e65da-6ba3-5e36-94c9-b6f4f5c8ce22"}, {"title": "朱全忠杀孙儒使者再度交恶", "start_year": null, "end_year": null, "time_original": "求好后未几；具体年日未载", "dynasty": "唐", "description": "朱全忠不久杀孙儒使者，两人再为仇敌。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "d27eeb54-1783-5318-8d61-dbf84a7d714d"}, {"title": "卢彦威光启末逐杨全玫自称留后", "start_year": null, "end_year": null, "time_original": "光启末；具体年未载", "dynasty": "唐", "description": "德州刺史卢彦威在光启末驱逐义昌节度使杨全玫，自称留后并求旌节，朝廷未准。", "phases": [], "location_name": "德州、义昌", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d6a97703-4a83-54e3-9bc3-0e255d7a1509"}, {"title": "王镕罗弘信代请，卢彦威获义昌节度使", "start_year": 890, "end_year": 890, "time_original": "890年六月条；张浚用兵时", "dynasty": "唐", "description": "王镕、罗弘信趁张浚用兵，为卢彦威请求旌节，朝廷遂以卢彦威为义昌节度使。", "phases": [], "location_name": "义昌", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e4bbf440-b113-5c46-a5db-b74db1897381"}, {"title": "张浚会诸镇军于晋州", "start_year": 890, "end_year": 890, "time_original": "890年六月后条；具体日未载", "dynasty": "唐", "description": "张浚在晋州会合宣武、镇国、静难、凤翔、保大、定难诸军。", "phases": [], "location_name": "晋州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "803bd8d0-1a01-5c1d-9636-515da426f818"}, {"title": "义成军改名宣义", "start_year": 890, "end_year": 890, "time_original": "890年六月条；具体日未载", "dynasty": "唐", "description": "朝廷将义成军更名为宣义。", "phases": [], "location_name": "义成军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c34c2370-6f4d-5aff-88f8-bdf882b58927"}, {"title": "朱全忠任宣武宣义节度使", "start_year": 890, "end_year": 890, "time_original": "890年六月辛未", "dynasty": "唐", "description": "朝廷以朱全忠为宣武、宣义节度使。", "phases": [], "location_name": "宣武、宣义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e2e890bd-7eeb-5608-b1e9-71435c4d5d40"}, {"title": "朱全忠辞宣义请胡真，朝廷从之", "start_year": 890, "end_year": 890, "time_original": "890年六月辛未条后", "dynasty": "唐", "description": "朱全忠因正有事徐、杨，认为征兵遣戍范围辽阔，辞宣义，请以胡真为节度使，朝廷同意。胡真任内，赋出入仍受朱全忠控制。", "phases": [], "location_name": "宣义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6e7ce006-bc06-5827-83c7-29199a66ea59"}, {"title": "胡真入统军后朱全忠复兼两镇", "start_year": null, "end_year": null, "time_original": "胡真入为统军后；具体年日未载", "dynasty": "唐", "description": "胡真入为统军后，朱全忠最终兼任宣武、宣义两镇节度使，不再领淮南。", "phases": [], "location_name": "宣武、宣义、淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2d681206-6c11-5c84-9a70-c47b68794898"}, {"title": "官军抵阴地关", "start_year": 890, "end_year": 890, "time_original": "890年七月", "dynasty": "唐", "description": "讨河东官军抵达阴地关。", "phases": [], "location_name": "阴地关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f0ea44b2-4f34-5faa-a7d8-8bbca0776f38"}, {"title": "葛从周夜入潞州援守军", "start_year": 890, "end_year": 890, "time_original": "890年七月", "dynasty": "唐", "description": "朱全忠遣葛从周率骑兵，潜自壶关夜抵潞州，冲破围军进入城内。", "phases": [], "location_name": "壶关、潞州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8f32033b-a24a-5f37-ba63-10c4936a22a3"}, {"title": "李谠等攻泽州，张全义朱友裕应援", "start_year": 890, "end_year": 890, "time_original": "890年七月", "dynasty": "唐", "description": "朱全忠遣李谠、李重胤、邓季筠攻泽州李罕之，又遣张全义、朱友裕驻军泽州北，应援葛从周。《通鉴》称邓季筠为下邑人。", "phases": [], "location_name": "泽州、泽州北", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0be33b70-3b9e-53ab-9cd4-3b001a851a7d"}, {"title": "张浚分兵令孙揆赴潞州", "start_year": 890, "end_year": 890, "time_original": "890年七月后条；八月发晋州前", "dynasty": "唐", "description": "朱全忠上奏请孙揆赴镇，张浚亦担忧昭义为汴军所据，分兵令孙揆率往潞州。", "phases": [], "location_name": "潞州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f737f08e-763b-5bba-a827-7204f045f0a4"}, {"title": "李存孝伏长子擒孙揆韩归范", "start_year": 890, "end_year": 890, "time_original": "890年八月乙丑", "dynasty": "唐", "description": "孙揆自晋州出发，李存孝在长子西谷设伏，俘获孙揆、赐旌节中使韩归范及牙兵，追杀余众至刁黄岭。", "phases": [], "location_name": "晋州、长子西谷、刁黄岭", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "868b517a-dd43-5930-9144-8b8cca3d569c"}, {"title": "李存孝徇孙揆韩归范于潞州城下", "start_year": null, "end_year": null, "time_original": "孙揆被俘后；具体日未载", "dynasty": "唐", "description": "李存孝械系孙揆、韩归范，在潞州城下展示，讥令葛从周速归使孙揆赴任，随后送交李克用。", "phases": [], "location_name": "潞州城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9838aad4-aadf-52be-bfca-3f0f400a7307"}, {"title": "孙揆拒李克用任用而遇害", "start_year": null, "end_year": null, "time_original": "被俘后既而；具体年日未载", "dynasty": "唐", "description": "李克用囚孙揆后，试图诱其任河东副使，孙揆拒绝。李克用命用锯处死孙揆，书载其至死骂不绝声。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "53ca0896-d0b2-58c7-b12a-26981e9d4478"}, {"title": "孙儒进攻润州", "start_year": 890, "end_year": 890, "time_original": "890年八月丙寅", "dynasty": "唐", "description": "孙儒进攻润州。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "46208bba-3d77-5279-a567-5339810ff28f"}]'::jsonb)
