SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "张浚率诸军及邠、宁、鄜、夏部众出京师，昭宗在安喜楼饯行。张浚私言先除外忧再除内患，杨复恭偷听得知。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p021·原文件第52行", "note": "原文：壬子，张浚帅诸军五十二都及邠、宁、鄜、夏杂虏合五万人发京师，上御安喜楼饯之。浚屏左右言于上曰：“俟臣先除外忧，然后为陛下除内患。”杨复恭窃听，闻之。两军中尉饯浚于长乐坂，复恭属浚酒，浚辞以醉，复恭戏之曰：“相公杖钺专征，作态邪？”浚曰：“俟平贼还，方见作态耳！”复恭益忌之。癸丑，削夺李罕之官爵。六月，以孙揆为昭义节度使，充招讨副使。；核对说明：五十二都、合五万为史载编制与规模，不独立核实。除内患为张浚意图，不记为已发生内廷清洗。", "status": "draft", "id": "6a76ffc4-578f-5dce-930a-1d52dc1ca50e", "subject_id": "0161dd19-bcd0-5563-a14c-522908fbd7bc", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "890年五月壬子", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p021·原文件第52行", "note": "原文：壬子，张浚帅诸军五十二都及邠、宁、鄜、夏杂虏合五万人发京师，上御安喜楼饯之。浚屏左右言于上曰：“俟臣先除外忧，然后为陛下除内患。”杨复恭窃听，闻之。两军中尉饯浚于长乐坂，复恭属浚酒，浚辞以醉，复恭戏之曰：“相公杖钺专征，作态邪？”浚曰：“俟平贼还，方见作态耳！”复恭益忌之。癸丑，削夺李罕之官爵。六月，以孙揆为昭义节度使，充招讨副使。；核对说明：五十二都、合五万为史载编制与规模，不独立核实。除内患为张浚意图，不记为已发生内廷清洗。", "status": "draft", "id": "1a14be98-e01c-55e7-aea4-a7560e32fd70", "subject_id": "0161dd19-bcd0-5563-a14c-522908fbd7bc", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记张浚：出师及私言者。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p021·原文件第52行", "note": "原文：壬子，张浚帅诸军五十二都及邠、宁、鄜、夏杂虏合五万人发京师，上御安喜楼饯之。浚屏左右言于上曰：“俟臣先除外忧，然后为陛下除内患。”杨复恭窃听，闻之。两军中尉饯浚于长乐坂，复恭属浚酒，浚辞以醉，复恭戏之曰：“相公杖钺专征，作态邪？”浚曰：“俟平贼还，方见作态耳！”复恭益忌之。癸丑，削夺李罕之官爵。六月，以孙揆为昭义节度使，充招讨副使。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "2ac3d7f1-d23d-5749-af36-332b539cddba", "subject_id": "0ab7d6a4-deb7-5601-86cd-77e4e2b19fc2", "source_id": "bd4c6687-4b2a-5664-a07b-3f5f5d44f014"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "张浚：出师及私言者。", "citation": "卷258·大顺元年（890）·zztj-v258-y0890-p021·原文件第52行", "note": "原文：壬子，张浚帅诸军五十二都及邠、宁、鄜、夏杂虏合五